<?php
namespace App\Http\Controllers;

use Illuminate\Database\QueryException;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;

class OfficeController extends Controller
{
 public function invoices(Request $r){$q=trim((string)$r->q);$status=trim((string)$r->status);$invoices=DB::table('invoices as i')->join('repairs as x','x.id','=','i.repair_id')->join('customers as c','c.id','=','x.customer_id')->join('devices as d','d.id','=','x.device_id')->select('i.*','x.ticket_no','c.full_name as customer_name','c.phone','d.brand','d.model')->when($q,fn($b)=>$b->where(fn($w)=>$w->where('i.invoice_no','like',"%$q%")->orWhere('x.ticket_no','like',"%$q%")->orWhere('c.full_name','like',"%$q%")->orWhere('c.phone','like',"%$q%")))->when($status,fn($b)=>$b->where('i.payment_status',$status))->orderByDesc('i.issued_at')->get();return view('office.invoices',compact('invoices','q','status'));}
 private function repair(int $id){return DB::table('repairs as r')->join('customers as c','c.id','=','r.customer_id')->join('devices as d','d.id','=','r.device_id')->select('r.*','c.full_name as customer_name','d.brand','d.model')->where('r.id',$id)->first();}
 public function invoiceCreate(Request $r){$repair=$this->repair((int)$r->repair_id);abort_unless($repair,404);if($id=DB::table('invoices')->where('repair_id',$repair->id)->value('id'))return redirect()->route('invoices.show',$id);return view('office.invoice-create',['repair'=>$repair,'subtotal'=>(float)($repair->total_cost>0?$repair->total_cost:$repair->estimated_cost)]);}
 public function invoiceStore(Request $r){$v=$r->validate(['repair_id'=>'required|integer','subtotal'=>'required|numeric|min:0','discount'=>'required|numeric|min:0','notes'=>'nullable']);$total=max(0,$v['subtotal']-$v['discount']);$no=generate_code('INV');$id=DB::table('invoices')->insertGetId(['invoice_no'=>$no,'repair_id'=>$v['repair_id'],'subtotal'=>$v['subtotal'],'discount'=>$v['discount'],'total'=>$total,'paid_amount'=>0,'payment_status'=>'unpaid','notes'=>$v['notes']?:null,'created_by'=>current_user()['id'],'issued_at'=>now()]);return redirect()->route('invoices.show',$id)->with('success','Invoice created successfully.');}
 public function invoiceShow(int $id){$invoice=DB::table('invoices as i')->join('repairs as r','r.id','=','i.repair_id')->join('customers as c','c.id','=','r.customer_id')->join('devices as d','d.id','=','r.device_id')->leftJoin('users as u','u.id','=','i.created_by')->select('i.*','r.ticket_no','r.labor_cost','r.parts_cost','r.fault_description','c.full_name as customer_name','c.phone','c.email','c.address','d.brand','d.model','d.imei','u.name as created_by_name')->where('i.id',$id)->first();abort_unless($invoice,404);$payments=DB::table('payments as p')->leftJoin('users as u','u.id','=','p.received_by')->select('p.*','u.name as received_by_name')->where('p.invoice_id',$id)->orderByDesc('p.paid_at')->get();return view('office.invoice-show',['invoice'=>$invoice,'payments'=>$payments,'balance'=>(float)$invoice->total-(float)$invoice->paid_amount]);}
 public function payment(Request $r,int $id){$invoice=DB::table('invoices')->find($id);abort_unless($invoice,404);$remaining=(float)$invoice->total-(float)$invoice->paid_amount;$v=$r->validate(['amount'=>"required|numeric|min:0.01|max:$remaining",'method'=>'required|in:cash,mobile_money,bank,card','reference'=>'nullable']);DB::transaction(function()use($id,$invoice,$v){DB::table('payments')->insert(['invoice_id'=>$id,'amount'=>$v['amount'],'method'=>$v['method'],'reference_no'=>$v['reference']?:null,'received_by'=>current_user()['id'],'paid_at'=>now()]);$paid=(float)$invoice->paid_amount+(float)$v['amount'];DB::table('invoices')->where('id',$id)->update(['paid_amount'=>$paid,'payment_status'=>$paid>=(float)$invoice->total?'paid':'partial']);});return back()->with('success','Payment recorded successfully.');}
 public function notifications(){return view('office.notifications',['rows'=>DB::table('notifications as n')->leftJoin('repairs as r','r.id','=','n.repair_id')->leftJoin('customers as c','c.id','=','n.customer_id')->select('n.*','r.ticket_no','c.full_name as customer_name')->orderByDesc('n.created_at')->limit(200)->get()]);}
 public function technicians(){return view('office.technicians',['techs'=>DB::table('users as u')->leftJoin('repairs as r','r.technician_id','=','u.id')->select('u.*',DB::raw('COUNT(r.id) total_repairs'),DB::raw("SUM(CASE WHEN r.status IN ('completed','collected') THEN 1 ELSE 0 END) completed_repairs"),DB::raw("SUM(CASE WHEN r.status NOT IN ('completed','collected','cancelled') THEN 1 ELSE 0 END) active_repairs"))->where('u.role','technician')->groupBy('u.id')->orderBy('u.name')->get()]);}
 public function users(){return view('office.users',['users'=>DB::table('users')->orderByDesc('created_at')->get()]);}
 public function userCreate(){return view('office.user-create');}
 public function userStore(Request $r){$v=$r->validate(['name'=>'required','email'=>'required|email|unique:users,email','phone'=>'nullable','password'=>'required|min:8','role'=>'required|in:admin,receptionist,technician']);$id=DB::table('users')->insertGetId(['name'=>$v['name'],'email'=>strtolower($v['email']),'phone'=>$v['phone']?:null,'password'=>Hash::make($v['password']),'role'=>$v['role'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);log_activity('create','user',$id,'Created '.$v['role'].' account');return redirect()->route('users.index')->with('success','User account created.');}
 public function userStatus(Request $r,int $id){abort_if($id===(int)current_user()['id'],422,'You cannot deactivate your own account.');$v=$r->validate(['status'=>'required|in:active,inactive']);DB::table('users')->where('id',$id)->update(['status'=>$v['status']]);return back()->with('success','User status updated.');}
 public function settings(){return view('office.settings',['values'=>collect(['shop_name','shop_email','shop_phone','shop_address','currency','email_notifications'])->mapWithKeys(fn($k)=>[$k=>get_setting($k)])]);}
 public function settingsUpdate(Request $r){foreach(['shop_name','shop_email','shop_phone','shop_address','currency','email_notifications'] as $key)DB::table('settings')->updateOrInsert(['setting_key'=>$key],['setting_value'=>(string)$r->input($key),'updated_at'=>now()]);return back()->with('success','Settings saved successfully.');}
 public function reports(){ $summary=['repairs'=>DB::table('repairs')->count(),'completed'=>DB::table('repairs')->whereIn('status',['completed','collected'])->count(),'pending'=>DB::table('repairs')->whereNotIn('status',['completed','collected','cancelled'])->count(),'revenue'=>DB::table('payments')->sum('amount')];$monthly=collect(range(5,0))->map(function($n){$d=now()->subMonths($n);return(object)['label'=>$d->format('M Y'),'revenue'=>DB::table('payments')->whereYear('paid_at',$d->year)->whereMonth('paid_at',$d->month)->sum('amount')];});$statuses=DB::table('repairs')->select('status',DB::raw('COUNT(*) total'))->groupBy('status')->get();$technicians=DB::table('users as u')->leftJoin('repairs as r',function($j){$j->on('r.technician_id','=','u.id')->whereIn('r.status',['completed','collected']);})->select('u.name',DB::raw('COUNT(r.id) total'))->where('u.role','technician')->groupBy('u.id','u.name')->orderByDesc('total')->limit(5)->get();$brands=DB::table('devices as d')->join('repairs as r','r.device_id','=','d.id')->select('d.brand',DB::raw('COUNT(r.id) total'))->groupBy('d.brand')->orderByDesc('total')->limit(5)->get();return view('office.reports',compact('summary','monthly','statuses','technicians','brands'));}
}
